(()=>{'use strict';const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)];const toast=$('.prototype-toast'),dialog=$('.action-dialog');let timer;function feedback(message){clearTimeout(timer);toast.textContent=message;toast.hidden=false;timer=setTimeout(()=>toast.hidden=true,2600)}$$('[role="tab"]').forEach((tab,index,tabs)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();activate(tabs[next])})});function activate(tab){$$('[role="tab"]').forEach(item=>{const selected=item===tab;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1});$$('[role="tabpanel"]').forEach(panel=>panel.hidden=panel.dataset.panel!==tab.dataset.tab)}$('[data-event-filter]').addEventListener('change',event=>{let visible=0;$$('[data-event]').forEach(item=>{item.hidden=event.target.value!=='all'&&item.dataset.event!==event.target.value;if(!item.hidden)visible++});$('[data-event-empty]').hidden=visible>0;feedback(visible?`${visible} registro(s) exibido(s).`:'Nenhum registro encontrado.')});$$('[data-feedback]').forEach(button=>button.addEventListener('click',()=>feedback(button.dataset.feedback)));$$('[data-action]').forEach(button=>button.addEventListener('click',()=>{dialog.querySelector('h2').textContent=button.dataset.action;dialog.showModal()}));dialog.addEventListener('close',()=>{if(dialog.returnValue==='confirm')feedback('Registro salvo somente nesta demonstração.')});$('[data-theme-toggle]').addEventListener('click',event=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';event.currentTarget.setAttribute('aria-pressed',String(dark));event.currentTarget.setAttribute('aria-label',dark?'Ativar modo claro':'Ativar modo escuro')})})();
